import json

def parse(f):
    with open(f) as fh:
        # handle NDJSON or standard JSON
        content = fh.read().strip()
        try:
            return json.loads(content)
        except:
            # try parsing as concatenated JSON
            import re
            objs = []
            decoder = json.JSONDecoder()
            idx = 0
            while idx < len(content):
                obj, end = decoder.raw_decode(content, idx)
                objs.append(obj)
                idx = end
                while idx < len(content) and content[idx] in ' \n\r\t':
                    idx += 1
            return objs

baseline = parse('baseline-packages.json')
after = parse('after-cpm-packages.json')

def extract_packages(data):
    result = {}
    if isinstance(data, list):
        for item in data:
            if 'projects' in item:
                for proj in item['projects']:
                    pname = proj.get('path','')
                    for fw in proj.get('frameworks', []):
                        for pkg in fw.get('topLevelPackages', []):
                            key = (pname, pkg['id'])
                            result[key] = pkg.get('resolvedVersion', pkg.get('requestedVersion',''))
    elif isinstance(data, dict) and 'projects' in data:
        for proj in data['projects']:
            pname = proj.get('path','')
            for fw in proj.get('frameworks', []):
                for pkg in fw.get('topLevelPackages', []):
                    key = (pname, pkg['id'])
                    result[key] = pkg.get('resolvedVersion', pkg.get('requestedVersion',''))
    return result

